/* @autogenerated */
package net.civeira.phylax.feature.observe.store;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.LocalDate;
import java.time.ZoneOffset;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class JsonlTelemetryStorePurgeUnitTest {

  @TempDir
  Path root;

  private Path day(final int daysAgo, final int bytes) throws IOException {
    Path dir = root.resolve(LocalDate.now(ZoneOffset.UTC).minusDays(daysAgo).toString());
    Files.createDirectories(dir);
    Files.write(dir.resolve("logs.jsonl"), new byte[bytes]);
    Files.write(dir.resolve("spans.jsonl"), new byte[bytes]);
    return dir;
  }

  @Test
  @DisplayName("Logs and spans have their own retention; a day left empty is removed")
  void retentionByKind() throws IOException {
    Path recent = day(1, 10);
    Path middle = day(10, 10);
    Path old = day(30, 10);
    new JsonlTelemetryStore(root.toString()).purge(new RetentionPolicy(14, 7, 0));
    Assertions.assertTrue(Files.exists(recent.resolve("spans.jsonl")));
    Assertions.assertTrue(Files.exists(middle.resolve("logs.jsonl")));
    Assertions.assertFalse(Files.exists(middle.resolve("spans.jsonl")));
    Assertions.assertFalse(Files.exists(old));
  }

  @Test
  @DisplayName("Above the disk limit the oldest days go, never the current one")
  void diskLimit() throws IOException {
    Path today = day(0, 400_000);
    Path yesterday = day(1, 400_000);
    Path before = day(2, 400_000);
    new JsonlTelemetryStore(root.toString()).purge(new RetentionPolicy(90, 90, 1));
    Assertions.assertFalse(Files.exists(before));
    Assertions.assertFalse(Files.exists(yesterday));
    Assertions.assertTrue(Files.exists(today));
  }
}
